head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.trigger1_onclick = function(e) {
	wframe.setSrc("/sample/common_link/wframe_anchor_WPF-1336_(WSQ-1948)_wframe1.xml");
};

scwin.trigger2_onclick = function(e) {
	wframe.setSrc("/sample/common_link/wframe_anchor_WPF-1336_(WSQ-1948)_wframe2.xml");
};

scwin.checkValue = function() {
	if (((j) => j.length ? j : $('#mf_anchor1'))($('#anchor1')).length == 0) {
		return scwin.__getDom($p.id + 'wframe_anchor1').innerText;
	} else {
		return scwin.__getDom($p.id + 'anchor1').innerText;
	}
};

scwin.setValue = function() {
	if (((j) => j.length ? j : $('#mf_anchor1'))($('#anchor1')).length == 0) {
		(document.getElementById('wframe_anchor1') || document.getElementById('mf_wframe_anchor1')).click();
	} else {
		anchor1.click();
	}
};

scwin.onpageload = function() {
	window.alert1IsShowed = false;
	window.alert2IsShowed = false;
};
